/* Polices embarquées dans les PDF — Lato, Łukasz Dziedzic, licence SIL OFL 1.1.
 *
 * Pourquoi : sans police intégrée, un PDF s'appuie sur les 14 polices dites
 * standard, que chaque lecteur est censé fournir. En pratique tous ne le font
 * pas — Poppler, par exemple, substitue une police système dont les métriques
 * diffèrent, ce qui déforme l'espacement et peut faire chevaucher les lettres.
 * Un document destiné à être imprimé et adressé à une administration ne peut
 * pas dépendre de ce que le lecteur du destinataire a installé.
 *
 * Les deux graisses sont réduites aux caractères réellement utilisés
 * (latin-1 étendu, guillemets français, tirets, €, ², ·) : 22 Ko chacune au
 * lieu de 640 Ko. Régénérer avec fontTools.subset si le jeu de caractères
 * change — voir README.
 */
const POLICE_NOM = 'Lato';
const POLICE_REGULIERE = '';
const POLICE_GRASSE = '';

// Enregistre les polices sur un document jsPDF. Idempotent par document.
function installerPolices(doc) {
  doc.addFileToVFS('Lato-Regular.ttf', POLICE_REGULIERE);
  doc.addFont('Lato-Regular.ttf', POLICE_NOM, 'normal');
  doc.addFileToVFS('Lato-Bold.ttf', POLICE_GRASSE);
  doc.addFont('Lato-Bold.ttf', POLICE_NOM, 'bold');
  doc.setFont(POLICE_NOM, 'normal');
}
